<script setup lang="ts">
import ConsoleQueryButton from '../../components/console/ConsoleQueryButton.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import AccountImageInput from '../../components/console/AccountImageInput.vue'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import ConsumerIdentity from '../../components/tenant/ConsumerIdentity.vue'
import ConsumerMemberEditor from '../../components/tenant/ConsumerMemberEditor.vue'
import ConsumerWallet from '../../components/tenant/ConsumerWallet.vue'
import ConsumerAssetEditor from '../../components/tenant/ConsumerAssetEditor.vue'
import AdminConsole from '../../components/console/AdminConsole.vue'
import {dateTime} from '../../utils/update-center'
definePageMeta({layout:'tenant',key:route=>route.path})
type Metric={label:string;value:string}
type Assets={points:number;memberPoints:number;version:string;membership:{active:boolean;expiresAt:string|null}}
type Customer={wallet?:{points:number;balanceCents:number};member?:{growth:number;level:{id:string;name:string}|null;tags:{id:string;name:string}[]};assets?:Assets;userId:string;memberNumber?:string|null;version:number;phone:string;email:string;gender:'unknown'|'male'|'female';enabled:boolean;hasPassword:boolean;membership:{active:boolean;expiresAt:string|null}|null;user:{id:string;nickname:string|null;avatar:string|null};firstSeenAt:string|null;lastActivityAt:string|null;metrics:Metric[]}
type Application={key:string;name:string}
type Listing={memberOptions?:{defaultLevel?:{name:string};levels:{id:string;name:string}[];tags:{id:string;name:string}[]};canManageAssets?:boolean;canWrite:boolean;items:Customer[];total:number;page:number;pageSize:number;applications:Application[];applicationKey:string|null}
type Detail=Customer&{application:Application;fields:Metric[]}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/consumers'
const memberTarget=ref<Customer|null>(null),levelFilter=ref('all'),tagFilter=ref('all'),levelSearch=ref('all'),tagSearch=ref('all')
const q=ref(''),search=ref(''),applicationKey=ref(''),page=ref(1),pageSize=ref(20),busy=ref(false),loadAction=ref('initial')
const params=()=>new URLSearchParams({q:search.value,...(levelSearch.value!=='all'?{levelId:levelSearch.value}:{}),...(tagSearch.value!=='all'?{tagId:tagSearch.value}:{}),page:String(page.value),pageSize:String(pageSize.value),...(applicationKey.value?{applicationKey:applicationKey.value}:{})})
const initial=await useAsyncData<Listing>('tenant-consumers:'+auth.session.value?.id+':'+tenantId,(_nuxt,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
if(initial.error.value&&!auth.session.value)await navigateTo('/admin/login',{replace:true})
const rows=ref<Listing>(initial.data.value??{canWrite:false,items:[],total:0,page:1,pageSize:20,applications:[],applicationKey:null}),error=ref(initial.error.value?.message||'')
applicationKey.value=rows.value.applicationKey||''
const walletTarget=ref<Customer|null>(null)
const assetTarget=ref<Customer|null>(null),assetKind=ref<'points.add'|'membership.set'>('points.add'),assetBusy=ref(false),assetReading=ref(false)
function openAssets(row:Customer,kind:'points.add'|'membership.set'){if(mutation.value||assetBusy.value||!rows.value.canManageAssets)return;modal.value=false;assetKind.value=kind;assetTarget.value=row}
function assetSaved(assets:Assets){const row=rows.value.items.find(r=>r.userId===assetTarget.value?.userId);if(row){row.assets=assets;row.membership=assets.membership}if(detail.value&&detail.value.userId===assetTarget.value?.userId){detail.value.assets=assets;detail.value.membership=assets.membership}}
const selected=ref<(string|number)[]>([]),editOpen=ref(false),editing=ref<Customer|null>(null),form=reactive({userId:'',nickname:'',avatar:null as string|null,phone:'',email:'',gender:'unknown' as 'unknown'|'male'|'female',enabled:true,password:'',confirmPassword:''}),imageBusy=ref(false),formError=ref(''),mutation=ref<'save'|'delete'|null>(null),deleteOpen=ref(false),deleteUsers=ref<{userId:string;memberNumber?:string|null;version:number}[]>([]),deleteError=ref(''),toast=useToast()
const columns=[{accessorKey:'userId',header:'用户'},{accessorKey:'phone',header:'手机号'},{id:'points',header:'积分余额'},{id:'level',header:'会员等级'},{id:'tags',header:'会员标签'},{id:'membership',header:'套餐订阅'},{id:'enabled',header:'用户状态'},{id:'actions',header:'操作'}]
function userActions(row:Customer){return [[...(row.assets?[{label:'账户资产',icon:'i-lucide-wallet',onSelect:()=>{walletTarget.value=row}}]:[]),{label:'等级与标签',icon:'i-lucide-badge-check',onSelect:()=>{memberTarget.value=row}},...(rows.value.canManageAssets?[{label:'调整积分',icon:'i-lucide-wallet',disabled:!row.enabled,onSelect:()=>row.wallet?walletTarget.value=row:openAssets(row,'points.add')},{label:'设置订阅',icon:'i-lucide-package',disabled:!row.enabled,onSelect:()=>openAssets(row,'membership.set')}]:[])],...(rows.value.canWrite?[[{label:'删除用户',icon:'i-lucide-trash-2',color:'error' as const,onSelect:()=>askDelete(row)}]]:[])]}
const lifetime=new AbortController();let disposed=false,listSequence=0,listController:AbortController|undefined,detailSequence=0,detailController:AbortController|undefined
async function load(source='refresh'){
 if(disposed)return;listController?.abort();listController=new AbortController();const current=++listSequence;busy.value=true;loadAction.value=source
 try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,listController.signal])});if(!disposed&&current===listSequence){rows.value=value;selected.value=[];page.value=value.page;applicationKey.value=value.applicationKey||'';error.value=''}}catch(e:any){if(!disposed&&current===listSequence){error.value=e.message||'用户读取失败';if(e.status===401)await navigateTo('/admin/login',{replace:true})}}finally{if(!disposed&&current===listSequence)busy.value=false}
}
function filter(source:'search'|'reset'){if(source==='reset'){q.value='';levelFilter.value='all';tagFilter.value='all'}levelSearch.value=levelFilter.value;tagSearch.value=tagFilter.value;search.value=q.value.trim();page.value=1;void load(source)}
function setPage(value:number){if(value===page.value)return;page.value=value;void load('page')}
function setPageSize(value:number){if(value===pageSize.value)return;pageSize.value=value;page.value=1;void load('page')}
function chooseApplication(value:string){assetTarget.value=null;memberTarget.value=null;levelFilter.value=levelSearch.value=tagFilter.value=tagSearch.value='all';applicationKey.value=value;modal.value=false;rows.value={...rows.value,items:[],total:0,applicationKey:null};page.value=1;void load('application')}
const modal=ref(false),target=ref<Customer|null>(null),detail=ref<Detail|null>(null),detailBusy=ref(false),detailSource=ref<'row'|'retry'>('row'),detailError=ref('')
function openDetail(row:Customer){target.value=row;detail.value=null;modal.value=true;void readDetail('row')}
async function readDetail(source:'row'|'retry'='retry'){
 if(!target.value||!rows.value.applicationKey||disposed)return;detailController?.abort();detailController=new AbortController();const current=++detailSequence,id=target.value.userId,key=rows.value.applicationKey;detailBusy.value=true;detailSource.value=source;detailError.value=''
 try{const value=await auth.api<Detail>(endpoint+'/'+encodeURIComponent(key)+'/'+encodeURIComponent(id),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,detailController.signal])});if(!disposed&&current===detailSequence&&modal.value&&rows.value.applicationKey===key)detail.value=value}catch(e:any){if(!disposed&&current===detailSequence&&modal.value)detailError.value=e.message||'用户详情读取失败'}finally{if(!disposed&&current===detailSequence)detailBusy.value=false}
}
function openEditor(row:Customer|null=null){if(mutation.value||!rows.value.canWrite||!rows.value.applicationKey)return;editing.value=row;Object.assign(form,{userId:row?.userId||'',nickname:row?.user.nickname||row?.userId||'',avatar:row?.user.avatar||null,phone:row?.phone||'',email:row?.email||'',gender:row?.gender||'unknown',enabled:row?.enabled??true,password:'',confirmPassword:''});formError.value='';editOpen.value=true}
async function save(){
 if(mutation.value||imageBusy.value||!rows.value.canWrite||!rows.value.applicationKey)return
 if(form.password!==form.confirmPassword){formError.value='两次输入的密码不一致';return}
 if(form.password&&(form.password.length<6||form.password.length>128)){formError.value='密码须为 6–128 位';return}
 if(!form.nickname.trim()){formError.value='请输入昵称';return}
 if(!editing.value&&!/^[a-zA-Z0-9]{3,64}$/.test(form.userId.trim())){formError.value='账号须为 3–64 位英文字母或数字';return}
 mutation.value='save';formError.value=''
 try{const base={nickname:form.nickname.trim(),avatar:form.avatar,phone:form.phone.trim(),email:form.email.trim(),gender:form.gender,enabled:form.enabled,...(form.password?{password:form.password}:{})};if(editing.value)await auth.api(endpoint+'/'+encodeURIComponent(rows.value.applicationKey)+'/'+encodeURIComponent(editing.value.userId),'PUT',{...base,version:editing.value.version},{signal:lifetime.signal});else await auth.api(endpoint,'POST',{...base,applicationKey:rows.value.applicationKey,userId:form.userId.trim()},{signal:lifetime.signal});if(!disposed){editOpen.value=false;modal.value=false;toast.add({title:editing.value?'用户已更新':'用户已新建',color:'success'});await load('mutation')}}catch(e){if(!disposed)formError.value=e instanceof Error?e.message:'保存失败'}finally{if(!disposed)mutation.value=null}
}
function askDelete(row?:Customer){if(mutation.value||!rows.value.canWrite)return;deleteUsers.value=(row?[row]:rows.value.items.filter(item=>selected.value.includes(item.userId))).map(item=>({userId:item.userId,version:item.version}));if(!deleteUsers.value.length)return;deleteError.value='';deleteOpen.value=true}
async function remove(){
 if(mutation.value||!rows.value.applicationKey||!deleteUsers.value.length)return
 mutation.value='delete';deleteError.value=''
 try{await auth.api(endpoint+'/delete','POST',{applicationKey:rows.value.applicationKey,users:deleteUsers.value,confirm:'删除用户'},{signal:lifetime.signal});if(!disposed){deleteOpen.value=false;modal.value=false;selected.value=[];toast.add({title:'用户已删除',color:'success'});await load('mutation')}}catch(e){if(!disposed)deleteError.value=e instanceof Error?e.message:'删除失败'}finally{if(!disposed)mutation.value=null}
}
watch(editOpen,open=>{if(!open){form.password='';form.confirmPassword=''}})
watch(modal,open=>{if(!open){detailSequence++;detailController?.abort();detailBusy.value=false;detail.value=null}})
onBeforeUnmount(()=>{disposed=true;listSequence++;detailSequence++;lifetime.abort();listController?.abort();detailController?.abort();busy.value=false;detailBusy.value=false})
</script>
<template><AdminConsole :refreshing="busy&&loadAction==='refresh'" @refresh="load('refresh')"><div class="space-y-5">
 <ConsolePageHeading title="用户列表"><template #actions><UButton v-if="rows.canWrite" icon="i-lucide-plus" :disabled="!!mutation||!rows.applicationKey" @click="openEditor()">新建用户</UButton></template></ConsolePageHeading>
 <form @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索账号、会员编号、昵称或手机号" :maxlength="100"/><USelect v-if="rows.applications.length>1" :model-value="applicationKey" :items="rows.applications.map(app=>({label:app.name,value:app.key}))" placeholder="选择应用" aria-label="用户所属应用" @update:model-value="chooseApplication"/><USelect v-model="levelFilter" :items="[{value:'all',label:'全部等级'},{value:'none',label:rows.memberOptions?.defaultLevel?.name||'普通会员'},...(rows.memberOptions?.levels||[]).map(l=>({value:l.id,label:l.name}))]" aria-label="筛选会员等级"/><USelect v-model="tagFilter" :items="[{value:'all',label:'全部标签'},...(rows.memberOptions?.tags||[]).map(t=>({value:t.id,label:t.name}))]" aria-label="筛选会员标签"/><div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="busy&&loadAction==='search'">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="busy&&loadAction==='reset'" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable class="users-desktop" :show-sequence="false" v-model:selected-ids="selected" :selectable="rows.canWrite" row-key="userId" :data="rows.items" :columns="columns" :page="page" :page-size="pageSize" :page-size-items="[10,20,50]" :total="rows.total" :client-pagination="false" :error="error" :empty-title="!rows.applicationKey&&rows.applications.length>1?'请选择应用':'暂无匹配的用户'" empty-description="客户使用应用后会显示在这里，也可以调整搜索条件。" min-table-width="0" @retry="load('retry')" @update:page="setPage" @update:page-size="setPageSize">
  <template #selection="{selectedCount}"><UButton v-if="rows.canWrite" color="error" variant="outline" icon="i-lucide-trash-2" :disabled="!selectedCount||!!mutation" @click="askDelete()">批量删除（{{selectedCount}}）</UButton></template>
  <template #errorActions><UButton :loading="busy&&loadAction==='retry'" @click="load('retry')">重试</UButton></template>
  <template #userId-cell="{row}"><ConsumerIdentity :user-id="row.original.userId" :profile="row.original.user"/></template>
  <template #phone-cell="{row}"><span class="break-all text-xs tabular-nums" :title="row.original.phone">{{row.original.phone||'—'}}</span></template>
  <template #points-cell="{row}"><span v-if="row.original.assets" class="font-semibold tabular-nums">{{(row.original.wallet?.points??row.original.assets.points).toLocaleString()}}</span><span v-else class="text-xs text-muted">无查看权限</span></template>
 <template #level-cell="{row}"><span class="whitespace-nowrap text-sm" :class="!row.original.member?.level&&'text-muted'">{{row.original.member?.level?.name||'普通会员'}}</span></template><template #tags-cell="{row}"><div v-if="row.original.member?.tags.length" class="flex min-w-0 flex-wrap gap-1"><UBadge v-for="tag in row.original.member.tags.slice(0,2)" :key="tag.id" color="neutral" variant="subtle" class="max-w-full truncate">{{tag.name}}</UBadge><span v-if="row.original.member.tags.length>2" class="text-xs text-muted">+{{row.original.member.tags.length-2}}</span></div><span v-else class="text-muted">—</span></template>
 <template #membership-cell="{row}"><UBadge v-if="row.original.membership" :color="row.original.membership.active?'primary':'neutral'" variant="subtle">{{row.original.membership.active?'已订阅':'未订阅'}}</UBadge><span v-else class="text-xs text-muted">无查看权限</span></template>
  <template #enabled-cell="{row}"><UBadge :color="row.original.enabled?'success':'neutral'" variant="subtle">{{row.original.enabled?'正常':'已停用'}}</UBadge></template>
  <template #metrics-cell="{row}"><div v-if="row.original.metrics.length" class="flex flex-wrap gap-x-5 gap-y-2"><span v-for="metric in row.original.metrics" :key="metric.label" class="whitespace-nowrap text-xs text-muted">{{metric.label}} <strong class="ml-1 font-medium tabular-nums text-default">{{metric.value}}</strong></span></div><span v-else class="text-muted">—</span></template>
  <template #firstSeenAt-cell="{row}"><span class="whitespace-nowrap text-xs">{{row.original.firstSeenAt?dateTime(row.original.firstSeenAt):'—'}}</span></template>
  <template #lastActivityAt-cell="{row}"><span class="whitespace-nowrap text-xs">{{row.original.lastActivityAt?dateTime(row.original.lastActivityAt):'—'}}</span></template>
  <template #actions-cell="{row}"><div class="flex items-center gap-3 whitespace-nowrap"><UButton variant="link" size="sm" class="px-0" @click="openDetail(row.original)">查看详情</UButton><UButton v-if="rows.canWrite" variant="link" size="sm" class="px-0" :disabled="!!mutation" @click="openEditor(row.original)">编辑</UButton><UDropdownMenu :items="userActions(row.original)"><UButton color="neutral" variant="link" size="sm" class="px-0" trailing-icon="i-lucide-chevron-down" :disabled="!!mutation">更多</UButton></UDropdownMenu></div></template>
 </ConsoleDataTable>
 <div class="users-mobile space-y-3"><UAlert v-if="error" color="error" :title="error"><template #actions><UButton :loading="busy&&loadAction==='retry'" @click="load('retry')">重试</UButton></template></UAlert><template v-else><div v-if="rows.canWrite&&rows.items.length" class="flex flex-wrap items-center gap-3"><UCheckbox :model-value="rows.items.every(r=>selected.includes(r.userId))" label="选择本页" @update:model-value="selected=$event?rows.items.map(r=>r.userId):[]"/><UButton v-if="selected.length" color="error" variant="outline" :disabled="!!mutation" @click="askDelete()">删除已选（{{selected.length}}）</UButton></div>
 <article v-for="row in rows.items" :key="row.userId" class="min-w-0 space-y-4 rounded-lg border border-default bg-default p-4"><div class="flex items-center justify-between gap-3"><div class="flex min-w-0 items-center gap-3"><UCheckbox v-if="rows.canWrite" :model-value="selected.includes(row.userId)" :aria-label="'选择 '+(row.user.nickname||row.userId)" @update:model-value="selected=$event?[...new Set([...selected,row.userId])]:selected.filter(id=>id!==row.userId)"/><ConsumerIdentity :user-id="row.userId" :profile="row.user"/></div><UBadge :color="row.enabled?'success':'neutral'" class="shrink-0">{{row.enabled?'正常':'停用'}}</UBadge></div>
 <p class="text-sm text-muted">手机号：{{row.phone||'—'}}</p><dl class="grid grid-cols-3 gap-3 text-sm"><div><dt class="text-xs text-muted">积分余额</dt><dd class="mt-1 font-medium">{{row.wallet?.points??row.assets?.points??'—'}}</dd></div><div class="min-w-0"><dt class="text-xs text-muted">会员等级</dt><dd class="mt-1 truncate" :title="row.member?.level?.name">{{row.member?.level?.name||'普通会员'}}</dd></div><div><dt class="text-xs text-muted">套餐订阅</dt><dd class="mt-1">{{row.membership?row.membership.active?'已订阅':'未订阅':'—'}}</dd></div></dl>
 <div v-if="row.member?.tags.length" class="flex flex-wrap gap-1"><UBadge v-for="tag in row.member.tags" :key="tag.id" color="neutral" class="max-w-full truncate">{{tag.name}}</UBadge></div><div class="flex justify-end gap-4 border-t border-default pt-3"><UButton variant="link" class="px-0" @click="openDetail(row)">查看详情</UButton><UButton v-if="rows.canWrite" variant="link" class="px-0" :disabled="!!mutation" @click="openEditor(row)">编辑</UButton><UDropdownMenu :items="userActions(row)"><UButton color="neutral" variant="link" class="px-0" trailing-icon="i-lucide-chevron-down" :disabled="!!mutation">更多</UButton></UDropdownMenu></div></article>
 <p v-if="!rows.items.length" class="py-8 text-center text-sm text-muted">暂无匹配的用户</p><div v-if="rows.total" class="flex flex-wrap items-center justify-between gap-3"><span class="text-xs text-muted">共 {{rows.total}} 条</span><div class="flex items-center gap-2"><UButton color="neutral" variant="outline" icon="i-lucide-chevron-left" aria-label="上一页" :disabled="page<=1" @click="setPage(page-1)"/><span class="text-xs">{{page}} / {{Math.ceil(rows.total/pageSize)}}</span><UButton color="neutral" variant="outline" icon="i-lucide-chevron-right" aria-label="下一页" :disabled="page*pageSize>=rows.total" @click="setPage(page+1)"/></div></div></template></div>
 <ConsoleDrawer v-model:open="modal" title="用户详情" description="查看客户资料与当前应用的使用概况。"><template #body>
  <UAlert v-if="detailError" color="error" :title="detailError"><template #actions><UButton :loading="detailBusy&&detailSource==='retry'" @click="readDetail('retry')">重试</UButton></template></UAlert>
  <p v-else-if="detailBusy&&!detail" role="status" class="text-sm text-muted">正在读取用户详情…</p>
  <div v-if="detail" class="drawer-detail space-y-6 text-default">
   <section class="space-y-4"><div class="space-y-4"><ConsumerIdentity :user-id="detail.userId" :profile="detail.user" prominent/><div class="flex items-center gap-2 text-xs text-muted"><UIcon name="i-lucide-layers" class="size-4"/><span>{{detail.application.name}}</span><UBadge :color="detail.enabled?'success':'neutral'" variant="subtle">{{detail.enabled?'正常':'已停用'}}</UBadge><UBadge v-if="detail.membership" :color="detail.membership.active?'primary':'neutral'" variant="subtle">{{detail.membership.active?'已订阅':'未订阅'}}</UBadge></div></div></section>
   <section v-if="detail.member" class="space-y-4"><h3 class="drawer-section-title">会员等级与标签</h3><dl class="drawer-facts"><dt>会员等级</dt><dd>{{detail.member.level?.name||'普通会员'}}</dd><dt>成长值</dt><dd>{{detail.member.growth}}</dd><dt>会员标签</dt><dd>{{detail.member.tags.map(t=>t.name).join('、')||'—'}}</dd></dl></section><section v-if="detail.wallet" class="space-y-4"><h3 class="drawer-section-title">账户资产</h3><dl class="drawer-facts"><dt>积分</dt><dd>{{detail.wallet.points}}</dd><dt>人民币余额</dt><dd>{{Math.trunc(detail.wallet.balanceCents/100)}}.{{String(detail.wallet.balanceCents%100).padStart(2,'0')}} 元</dd></dl></section><section v-if="detail.assets" class="space-y-4"><h3 class="drawer-section-title">{{detail.wallet?'历史积分与订阅':'积分与订阅'}}</h3><dl class="drawer-facts"><dt>普通积分</dt><dd>{{detail.assets.points}}</dd><dt>会员剩余额度</dt><dd>{{detail.assets.memberPoints}}</dd><dt>会员到期</dt><dd>{{detail.assets.membership.active?(detail.assets.membership.expiresAt?dateTime(detail.assets.membership.expiresAt):'长期有效'):'—'}}</dd></dl></section>
   <section class="space-y-4"><h3 class="drawer-section-title">账号资料</h3><dl class="drawer-facts"><dt>会员编号</dt><dd>{{detail.memberNumber||'未分配'}}</dd><dt>手机号</dt><dd>{{detail.phone||'—'}}</dd><dt>邮箱</dt><dd>{{detail.email||'—'}}</dd><dt>性别</dt><dd>{{({unknown:'未知',male:'男',female:'女'})[detail.gender]||'未知'}}</dd><dt>登录密码</dt><dd>{{detail.hasPassword?'已设置':'未设置'}}</dd><dt v-if="!detail.assets&&detail.membership?.active">会员到期</dt><dd v-if="!detail.assets&&detail.membership?.active">{{detail.membership.expiresAt?dateTime(detail.membership.expiresAt):'—'}}</dd></dl></section>
   <section v-if="detail.metrics.length||detail.fields.length" class="space-y-4"><h3 class="drawer-section-title">应用概况</h3><div class="space-y-5">
    <dl v-if="detail.metrics.length" class="grid grid-cols-2 gap-x-5 gap-y-5 pb-1 sm:grid-cols-3"><div v-for="metric in detail.metrics" :key="metric.label" class="min-w-0"><dt class="text-xs text-muted">{{metric.label}}</dt><dd class="mt-2 break-all text-2xl font-semibold tabular-nums leading-tight">{{metric.value}}</dd></div></dl>
    <dl v-if="detail.fields.length" class="space-y-3"><div v-for="field in detail.fields" :key="field.label" class="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1"><dt class="text-xs text-muted">{{field.label}}</dt><dd class="break-all text-lg font-semibold tabular-nums">{{field.value}}</dd></div></dl>
   </div></section>
   <section class="space-y-4"><h3 class="drawer-section-title">记录时间</h3><dl class="drawer-facts"><dt>首次记录</dt><dd>{{detail.firstSeenAt?dateTime(detail.firstSeenAt):'—'}}</dd><dt>最近记录</dt><dd>{{detail.lastActivityAt?dateTime(detail.lastActivityAt):'—'}}</dd></dl></section>
  </div>
 </template></ConsoleDrawer>
 <ConsoleDrawer v-model:open="editOpen" :title="editing?'编辑用户':'新建用户'" description="设置用户资料、登录密码与访问状态。" wide :dismissible="!mutation&&!imageBusy" :close="!mutation&&!imageBusy"><template #body>
  <form id="customer-form" novalidate class="customer-editor space-y-6" @submit.prevent="save"><UAlert v-if="formError" color="error" :title="formError"/>
   <ConsoleSettingsField label="头像"><AccountImageInput v-model="form.avatar" label="用户头像" portal="tenant" :endpoint="'/admin/tenants/'+encodeURIComponent(tenantId)+'/materials/'+encodeURIComponent(rows.applicationKey||'')" :disabled="!!mutation" @busy="imageBusy=$event"/></ConsoleSettingsField>
   <ConsoleSettingsField label="账号" input-id="customer-account"><ConsoleInput id="customer-account" v-model="form.userId" pattern="[a-zA-Z0-9]{3,64}" :minlength="3" :disabled="!!editing||!!mutation" :maxlength="64" required placeholder="请输入账号"/><p class="mt-2 text-xs text-muted">账号须为 3–64 位英文字母或数字，创建后不可修改。</p></ConsoleSettingsField>
   <ConsoleSettingsField label="昵称" input-id="customer-nickname"><ConsoleInput id="customer-nickname" v-model="form.nickname" :maxlength="32" :disabled="!!mutation" required placeholder="请输入昵称"/></ConsoleSettingsField>
   <ConsoleSettingsField label="手机号" input-id="customer-phone"><ConsoleInput id="customer-phone" v-model="form.phone" type="tel" :maxlength="32" :disabled="!!mutation" placeholder="请输入手机号"/></ConsoleSettingsField>
   <ConsoleSettingsField label="邮箱" input-id="customer-email"><ConsoleInput id="customer-email" v-model="form.email" type="email" :maxlength="254" :disabled="!!mutation" placeholder="请输入邮箱"/></ConsoleSettingsField>
   <ConsoleSettingsField label="性别"><URadioGroup v-model="form.gender" orientation="horizontal" :items="[{value:'unknown',label:'未知'},{value:'male',label:'男'},{value:'female',label:'女'}]" :disabled="!!mutation"/></ConsoleSettingsField>
   <ConsoleSettingsField :label="editing?'新密码':'密码'" input-id="customer-password"><ConsoleInput id="customer-password" v-model="form.password" type="password" autocomplete="new-password" :maxlength="128" :disabled="!!mutation" placeholder="请输入密码"/><p class="mt-2 text-xs text-muted">{{editing?'留空保留原密码，修改后旧会话会失效。':'可留空，之后可在编辑用户中设置。'}}</p></ConsoleSettingsField>
   <ConsoleSettingsField label="确认密码" input-id="customer-confirm-password"><ConsoleInput id="customer-confirm-password" v-model="form.confirmPassword" type="password" autocomplete="new-password" :maxlength="128" :disabled="!!mutation" placeholder="请再次输入密码"/></ConsoleSettingsField>
   <ConsoleSettingsField label="用户状态"><USwitch v-model="form.enabled" :label="form.enabled?'启用':'停用'" :disabled="!!mutation"/></ConsoleSettingsField>
  </form>
 </template><template #footer><ConsoleFormActions class="w-full"><UButton color="neutral" variant="outline" :disabled="!!mutation||imageBusy" @click="editOpen=false">取消</UButton><UButton type="submit" form="customer-form" :loading="mutation==='save'" :disabled="!!mutation||imageBusy">保存</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <UModal v-model:open="deleteOpen" title="删除用户？" description="删除后用户无法继续访问，历史作品、订单和交易记录保留。" :dismissible="!mutation" :close="!mutation"><template #body><p class="text-sm">将删除 {{deleteUsers.length}} 个用户。</p><UAlert v-if="deleteError" class="mt-4" color="error" :title="deleteError"/></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="!!mutation" @click="deleteOpen=false">取消</UButton><UButton color="error" :loading="mutation==='delete'" :disabled="!!mutation" @click="remove">确认删除</UButton></div></template></UModal>
<ConsumerWallet v-if="walletTarget&&rows.applicationKey" :key="rows.applicationKey+walletTarget.userId" :endpoint="endpoint+'/'+encodeURIComponent(rows.applicationKey)+'/'+encodeURIComponent(walletTarget.userId)+'/wallet'" :can-write="!!rows.canManageAssets" @close="walletTarget=null" @saved="load('mutation')"/>
<ConsumerAssetEditor v-if="assetTarget&&rows.applicationKey" :key="rows.applicationKey+assetTarget.userId+assetKind" :endpoint="endpoint+'/'+encodeURIComponent(rows.applicationKey)+'/'+encodeURIComponent(assetTarget.userId)+'/assets'" :kind="assetKind" @busy="assetBusy=$event" @reading="assetReading=$event" @close="assetTarget=null" @saved="assetSaved"/>
<ConsumerMemberEditor v-if="memberTarget&&rows.applicationKey" :key="memberTarget.userId+rows.applicationKey" :endpoint="endpoint+'/'+encodeURIComponent(rows.applicationKey)+'/'+encodeURIComponent(memberTarget.userId)+'/membership'" @close="memberTarget=null" @saved="modal=false;load('mutation')"/></div></AdminConsole></template>

